    public void testRandom_int_int_int_boolean_charArray_Random() throws Exception {
        char[] chars = {'a', 'b', 'c'};
        Random random = new Random();
        String result = RandomStringUtils.random(10, 0, chars.length, false, false, chars, random);
        assertNotNull(result);
        assertEquals(10, result.length());
        for (char c : result.toCharArray()) {
            assertTrue("Character not in chars array", contains(chars, c));
        }
    }

    @Test
    public void testRandom_int_String() throws Exception {
        String chars = "abc";
        String result = RandomStringUtils.random(10, chars);
        assertNotNull(result);
        assertEquals(10, result.length());
        for (char c : result.toCharArray()) {
            assertTrue("Character not in chars string", chars.indexOf(c) != -1);
        }
    }

    @Test
    public void testRandom_int_String_null() throws Exception {
        String result = RandomStringUtils.random(10, (String) null);
        assertNotNull(result);
        assertEquals(10, result.length());
    }

    @Test(expected = NegativeArraySizeException.class)
    public void testRandom_negativeCount() throws Exception {
        RandomStringUtils.random(-1);
    }

    private boolean contains(char[] array, char value) {
        for (char c : array) {
            if (c == value) {
                return true;
            }
        }
        return false;
    }
}
