@Before
    public void before(){
    }

    @After
    public void after(){
    }

    @Test
    public void testCreateNumber_Null() throws Exception {
        Number number = NumberUtils.createNumber(null);
        Assert.assertNull(number);
    }

    @Test
    public void testCreateNumber_Blank() throws Exception {
        try {
            NumberUtils.createNumber("");
            Assert.fail();
        } catch (NumberFormatException e) {
            Assert.assertEquals("A blank string is not a valid number", e.getMessage());
        }
    }

    @Test
    public void testCreateNumber_StartsWithMinus() throws Exception {
        Number number = NumberUtils.createNumber("--123");
        Assert.assertNull(number);
    }

    @Test
    public void testCreateNumber_Hexadecimal() throws Exception {
        Number number = NumberUtils.createNumber("0x123");
        Assert.assertEquals(291L, number.longValue());
    }

    @Test
    public void testCreateNumber_Exponent() throws Exception {
        Number number = NumberUtils.createNumber("123.456e2");
        Assert.assertEquals(12345.6, number.doubleValue(), 0.01);
    }

    @Test
    public void testCreateNumber_Float() throws Exception {
        Number number = NumberUtils.createNumber("123.456f");
        Assert.assertEquals(123.456f, number.floatValue(), 0.01f);
    }

    @Test
    public void testCreateNumber_Double() throws Exception {
        Number number = NumberUtils.createNumber("123.456d");
        Assert.assertEquals(123.456, number.doubleValue(), 0.01);
    }

    @Test
    public void testCreateNumber_Long() throws Exception {
        Number number = NumberUtils.createNumber("123l");
        Assert.assertEquals(123L, number.longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() throws Exception {
        Number number = NumberUtils.createNumber("12345678901234567890");
        Assert.assertEquals(new BigInteger("12345678901234567890"), number);
    }

    @Test
    public void testCreateNumber_BigDecimal() throws Exception {
        Number number = NumberUtils.createNumber("123.456");
        Assert.assertEquals(new BigDecimal("123.456"), number);
    }

    @Test
    public void testCreateNumber_Invalid() throws Exception {
        try {
            NumberUtils.createNumber("abc");
            Assert.fail();
        } catch (NumberFormatException e) {
            Assert.assertEquals("abc is not a valid number.", e.getMessage());
        }
    }
}
