import org.junit.Test;
import org.junit.Assert;
import org.junit.Before;
import org.junit.After; 
import org.junit.Assert.*;
import org.junit.Ignore;
import org.junit.BeforeClass;
import org.junit.AfterClass;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.junit.Rule;
import org.junit.rules.ExpectedException;
import org.mockito.Mockito.*
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;
import java.math.BigDecimal;
import java.math.BigInteger;

public class NumberUtilsTest{
@Before
    public void setUp(){
    }

    @Test
    public void testCreateNumber_Null(){
        Assert.assertNull(org.apache.commons.lang.NumberUtils.createNumber(null));
    }

    @Test
    public void testCreateNumber_Empty(){
        try{
            org.apache.commons.lang.NumberUtils.createNumber("");
            Assert.fail();
        }catch(Exception e){
            Assert.assertEquals("\"\" is not a valid number.", e.getMessage());
        }
    }

    @Test
    public void testCreateNumber_SingleNonDigit(){
        try{
            org.apache.commons.lang.NumberUtils.createNumber("a");
            Assert.fail();
        }catch(Exception e){
            Assert.assertEquals("a is not a valid number.", e.getMessage());
        }
    }

    @Test
    public void testCreateNumber_DoubleHyphens(){
        Assert.assertNull(org.apache.commons.lang.NumberUtils.createNumber("--1"));
    }

    @Test
    public void testCreateNumber_Hex(){
        Assert.assertEquals(new BigInteger("10", 16), org.apache.commons.lang.NumberUtils.createNumber("0xa"));
    }

    @Test
    public void testCreateNumber_NegativeHex(){
        Assert.assertEquals(new BigInteger("-10", 16), org.apache.commons.lang.NumberUtils.createNumber("-0xa"));
    }

    @Test
    public void testCreateNumber_Integer(){
        Assert.assertEquals(new Integer(10), org.apache.commons.lang.NumberUtils.createNumber("10"));
    }

    @Test
    public void testCreateNumber_Long(){
        Assert.assertEquals(new Long(10), org.apache.commons.lang.NumberUtils.createNumber("10l"));
    }

    @Test
    public void testCreateNumber_BigInteger(){
        Assert.assertEquals(new BigInteger("12345678901234567890"), org.apache.commons.lang.NumberUtils.createNumber("12345678901234567890"));
    }

    @Test
    public void testCreateNumber_Float(){
        Assert.assertEquals(new Float(10.5), org.apache.commons.lang.NumberUtils.createNumber("10.5f"));
    }

    @Test
    public void testCreateNumber_Double(){
        Assert.assertEquals(new Double(10.5), org.apache.commons.lang.NumberUtils.createNumber("10.5d"));
    }

    @Test
    public void testCreateNumber_BigDecimal(){
        Assert.assertEquals(new BigDecimal("10.5"), org.apache.commons.lang.NumberUtils.createNumber("10.5"));
    }

    @Test
    public void testCreateNumber_Exponential(){
        Assert.assertEquals(new Double(10.5), org.apache.commons.lang.NumberUtils.createNumber("1.05e1"));
    }

    @Test
    public void testCreateNumber_Invalid(){
        try{
            org.apache.commons.lang.NumberUtils.createNumber("a10.5");
            Assert.fail();
        }catch(Exception e){
            Assert.assertEquals("a10.5 is not a valid number.", e.getMessage());
        }
    }
}
