    public void testAbbreviate_EmptyString_ReturnsEmptyString(){
        //Arrange
        String str = "";
        int lower = 5;
        int upper = 10;
        String appendToEnd = "...";

        //Act
        String result = WordUtils.abbreviate(str, lower, upper, appendToEnd);

        //Assert
        assertEquals("", result);
    }

