    public void tearDown(){
    }

    @Test
    public void testCreateNumber_Null() throws Exception {
        Assert.assertNull(NumberUtils.createNumber(null));
    }

    @Test
    public void testCreateNumber_Blank() throws Exception {
        expectedException.expect(NumberFormatException.class);
        NumberUtils.createNumber("");
    }

    @Test
    public void testCreateNumber_Double() throws Exception {
        Assert.assertEquals(Double.valueOf("12.34"), NumberUtils.createNumber("12.34"));
    }

    @Test
    public void testCreateNumber_Float() throws Exception {
        Assert.assertEquals(Float.valueOf("12.34"), NumberUtils.createNumber("12.34f"));
    }

    @Test
    public void testCreateNumber_DoubleExp() throws Exception {
        Assert.assertEquals(Double.valueOf("12.34e5"), NumberUtils.createNumber("12.34e5"));
    }

    @Test
    public void testCreateNumber_Integer() throws Exception {
        Assert.assertEquals(Integer.valueOf("123"), NumberUtils.createNumber("123"));
    }

    @Test
    public void testCreateNumber_Long() throws Exception {
        Assert.assertEquals(Long.valueOf("123L"), NumberUtils.createNumber("123L"));
    }

    @Test
    public void testCreateNumber_BigInteger() throws Exception {
        Assert.assertEquals(new BigInteger("123456789012345678901234567890"), NumberUtils.createNumber("123456789012345678901234567890"));
    }

    @Test
    public void testCreateNumber_BigDecimal() throws Exception {
        Assert.assertEquals(new BigDecimal("123.456"), NumberUtils.createNumber("123.456"));
    }

    @Test
    public void testCreateNumber_Invalid() throws Exception {
        expectedException.expect(NumberFormatException.class);
        NumberUtils.createNumber("abc");
    }

    @Test
    public void testCreateNumber_Hex() throws Exception {
        Assert.assertEquals(Integer.valueOf("16", 16), NumberUtils.createNumber("0x10"));
    }

    @Test
    public void testCreateNumber_HexNegative() throws Exception {
        Assert.assertEquals(Integer.valueOf("-16", 16), NumberUtils.createNumber("-0x10"));
    }

    @Test
    public void testCreateNumber_WeirdJava() throws Exception {
        Assert.assertNull(NumberUtils.createNumber("--12"));
    }
}
