import java.io.Reader;
import java.io.Writer;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;

public class StrBuilderTest{
@Rule
    public ExpectedException expectedException = ExpectedException.none();

    private StrBuilder sb;

    @Before
    public void before(){
        sb = new StrBuilder();
    }

    @Test
    public void test_indexOf_StrMatcher_int_nullStrMatcher(){
        // given
        StrMatcher matcher = null;

        // when 
        int result = sb.indexOf(matcher, 0);

        // then
        Assert.assertEquals(-1, result);
    }

    @Test
    public void test_indexOf_StrMatcher_int_startIndexLessThanZero(){
        // given
        StrMatcher matcher = StrMatcher.charMatcher('a');

        // when 
        int result = sb.indexOf(matcher, -1);

        // then
        Assert.assertEquals(-1, result);
    }

    @Test
    public void test_indexOf_StrMatcher_int_startIndexGreaterThanOrEqualToSize(){
        // given
        StrMatcher matcher = StrMatcher.charMatcher('a');
        sb.append("abc");

        // when 
        int result = sb.indexOf(matcher, 5);

        // then
        Assert.assertEquals(-1, result);
    }

    @Test
    public void test_indexOf_StrMatcher_int_found(){
        // given
        StrMatcher matcher = StrMatcher.charMatcher('a');
        sb.append("abc");

        // when 
        int result = sb.indexOf(matcher, 0);

        // then
        Assert.assertEquals(0, result);
    }

    @Test
    public void test_indexOf_StrMatcher_int_notFound(){
        // given
        StrMatcher matcher = StrMatcher.charMatcher('d');
        sb.append("abc");

        // when 
        int result = sb.indexOf(matcher, 0);

        // then
        Assert.assertEquals(-1, result);
    }

    @Test
    public void test_indexOf_StrMatcher_int_emptyStrBuilder(){
        // given
        StrMatcher matcher = StrMatcher.charMatcher('a');

        // when 
        int result = sb.indexOf(matcher, 0);

        // then
        Assert.assertEquals(-1, result);
    }
}
