    @Test
    public void testUnescape(){
        Entities e = new Entities();
        String result = e.unescape("&amp;");
        assertEquals("&", result);

        result = e.unescape("&apos;");
        assertEquals("'", result);

        result = e.unescape("&lt;");
        assertEquals("<", result);

        result = e.unescape("&gt;");
        assertEquals(">", result);

        result = e.unescape("&quot;");
        assertEquals("\"", result);

        result = e.unescape("&invalid;");
        assertEquals("&invalid;", result);

        result = e.unescape("&invalid&amp;");
        assertEquals("&invalid&amp;", result);

        result = e.unescape("&#65;");
        assertEquals("A", result);

        result = e.unescape("&#x41;");
        assertEquals("A", result);

        result = e.unescape("&#xZZ;");
        assertEquals("&#xZZ;", result);
    }

    @Test
    public void testEntityValue(){
        Entities e = new Entities();
        e.addEntity("test", 65);
        int result = e.entityValue("test");
        assertEquals(65, result);
    }

