        timeZoneNameRule.appendTo(buffer, calendar);
        Assert.assertEquals(timeZoneNameRule.mDaylight, buffer.toString());
    }

    @Test
    public void testEstimateLength() {
        int estimateLength = timeZoneNameRule.estimateLength();
        Assert.assertNotEquals(0, estimateLength);
    }

    @Test
    public void testConstructor() {
        TimeZone timeZone = TimeZone.getDefault();
        Locale locale = Locale.getDefault();
        int style = DateFormat.FULL;
        TimeZoneNameRule rule = new TimeZoneNameRule(timeZone,locale,style);
        Assert.assertNotNull(rule);
    }

    @Test
    public void testGetTimeZoneDisplay() {
        TimeZone timeZone = TimeZone.getDefault();
        Locale locale = Locale.getDefault();
        int style = DateFormat.FULL;
        String standard = timeZoneNameRule.getTimeZoneDisplay(timeZone,false,style,locale);
        String daylight = timeZoneNameRule.getTimeZoneDisplay(timeZone,true,style,locale);
        Assert.assertNotNull(standard);
        Assert.assertNotNull(daylight);
    }
}
